// Assertion suite for AM font-token parsing, family matching and text unit scaling.
//
// Every fixture is a token that actually ships in the APK or in an APK-shipped
// project file, so a failure here means a real project would import wrong:
//
//   assets/hometab/beta_anim.xml                 "Roboto Black:com.google.android.gms.fonts?name=Roboto&weight=900"
//   assets/effects/presets/text-presets.xml      "googlefonts?name=Roboto&weight=400"
//   (generated by the web export path)           "SpaceGrotesk-Bold"
//
// Run: esbuild --bundle --platform=node → node, same as check_font_zip.ts.

import { familyKey, parseAmFontToken, sameFamily } from '../../src/engine/fontNames';
import { nearestFace, type FaceSpec } from '../../src/engine/fontRegistry';
import { amTextSizeToPx, pxToAmTextSize, textBlockHeight } from '../../src/engine/textMetrics';

let failures = 0;
function check(name: string, cond: boolean, detail?: unknown): void {
  if (cond) {
    console.log(`  ok   ${name}`);
  } else {
    failures++;
    console.log(`  FAIL ${name}${detail === undefined ? '' : ` :: ${JSON.stringify(detail)}`}`);
  }
}

console.log('parseAmFontToken — real AM tokens');
{
  const a = parseAmFontToken('Roboto Black:com.google.android.gms.fonts?name=Roboto&weight=900');
  check('display+provider: family', a.family === 'Roboto', a.family);
  check('display+provider: weight from query', a.weight === 900, a.weight);
  check('display+provider: normal style', a.style === 'normal', a.style);
  check('display+provider: provider kept', (a.provider || '').includes('gms.fonts'), a.provider);

  const b = parseAmFontToken('Oswald:com.google.android.gms.fonts?name=Oswald');
  check('no weight in query falls back to display', b.family === 'Oswald' && b.weight === 400, b);

  const c = parseAmFontToken('googlefonts?name=Roboto&weight=400');
  check('bare provider token', c.family === 'Roboto' && c.weight === 400, c);

  const d = parseAmFontToken('Hind-SemiBold');
  check('compact <Family>-<Weight>', d.family === 'Hind' && d.weight === 600, d);

  const e = parseAmFontToken('SpaceGrotesk-BoldItalic');
  check('italic suffix', e.family === 'Space Grotesk' && e.weight === 700 && e.style === 'italic', e);

  const f = parseAmFontToken('Roboto Medium:com.google.android.gms.fonts?name=Roboto&weight=500');
  check('display weight agrees with query', f.weight === 500, f.weight);

  const g = parseAmFontToken('NotoSansJP-Regular:com.google.android.gms.fonts?name=Noto+Sans+JP');
  check('percent/plus decoded family', g.family === 'Noto Sans JP', g.family);

  const h = parseAmFontToken('');
  check('empty token defaults to Roboto 400', h.family === 'Roboto' && h.weight === 400 && h.usedDefault, h);
}

console.log('familyKey / sameFamily');
{
  check('face suffix collapses', familyKey('Hind SemiBold') === familyKey('Hind'), familyKey('Hind SemiBold'));
  check('punctuation collapses', familyKey('PT_Sans-Narrow') === familyKey('PT Sans Narrow'));
  check('case collapses', familyKey('space grotesk') === familyKey('Space Grotesk'));
  check('distinct families stay distinct', familyKey('Roboto Mono') !== familyKey('Roboto'));
  check('condensed stays distinct', familyKey('Open Sans Condensed') !== familyKey('Open Sans'));
  check('black is a weight not a family', sameFamily('Roboto Black', 'Roboto'));
  check('different families do not match', !sameFamily('Hind', 'Lato'));
  check('empty never matches', !sameFamily('', 'Roboto'));
}

console.log('nearestFace');
{
  const faces: FaceSpec[] = [
    { family: 'Hind', weight: 300, style: 'normal' },
    { family: 'Hind', weight: 400, style: 'normal' },
    { family: 'Hind', weight: 700, style: 'normal' },
    { family: 'Hind', weight: 400, style: 'italic' },
  ];
  check('exact weight wins', nearestFace(faces, 700, 'normal')?.weight === 700);
  check('nearest weight', nearestFace(faces, 600, 'normal')?.weight === 700, nearestFace(faces, 600, 'normal'));
  check('italics available are used', nearestFace(faces, 400, 'italic')?.style === 'italic');
  check('style never beats weight', nearestFace(faces, 700, 'italic')?.weight === 700);
  check('empty list yields null', nearestFace([], 400, 'normal') === null);
}

console.log('textMetrics');
{
  // text-presets.xml: <text size="48.000000"> on a 1080 canvas.
  check('AM size 48 → 144 px em', amTextSizeToPx(48) === 144, amTextSizeToPx(48));
  check('px → AM round trip', Math.abs(pxToAmTextSize(amTextSizeToPx(48)) - 48) < 1e-9);
  check('one line box', Math.abs(textBlockHeight(144, 1, 1.2) - 172.8) < 1e-6, textBlockHeight(144, 1, 1.2));
  check('three line box', Math.abs(textBlockHeight(144, 3, 1.2) - 518.4) < 1e-6);
  check('zero lines still one', Math.abs(textBlockHeight(144, 0, 1.2) - 172.8) < 1e-6);
  check('missing lineHeight uses 1.2', Math.abs(textBlockHeight(100, 1, 0) - 120) < 1e-6);
}

console.log(failures === 0 ? '\nPASS' : `\n${failures} FAILED`);
process.exit(failures === 0 ? 0 : 1);
